css:
@page {
	size: A4 portrait;
	margin: 15mm 15mm 15mm 20mm;
}

.sb-ustva {
	color: #000;
	font-size: 9pt;
	line-height: 1.35;
}

.sb-ustva h1 {
	font-size: 15pt;
	font-weight: 600;
	margin: 0 0 1mm;
}

.sb-ustva h2 {
	font-size: 10.5pt;
	font-weight: 600;
	margin: 6mm 0 2mm;
}

.sb-ustva .sb-subtitle {
	color: #444;
	font-weight: 600;
	margin: 0 0 3mm;
}

.sb-ustva table {
	width: 100%;
	border-collapse: collapse;
}

.sb-ustva thead {
	display: table-header-group;
}

.sb-ustva tr,
.sb-ustva .sb-group {
	break-inside: avoid;
	page-break-inside: avoid;
}

.sb-ustva .sb-form {
	table-layout: fixed;
}

.sb-ustva .sb-head {
	margin: 3mm 0 5mm;
}

.sb-ustva .sb-label,
.sb-ustva .sb-value {
	padding: 0.8mm 2mm 0.8mm 0;
	text-align: left;
	vertical-align: top;
}

.sb-ustva .sb-label {
	color: #555;
	white-space: nowrap;
	width: 58mm;
}

.sb-ustva .sb-form th {
	border-bottom: 0.4mm solid #000;
	font-size: 8pt;
	font-weight: 600;
	padding: 1mm 1.5mm;
	text-align: left;
	vertical-align: bottom;
}

.sb-ustva .sb-form td {
	border-bottom: 0.2mm solid #bbb;
	padding: 1mm 1.5mm;
	vertical-align: top;
}

.sb-ustva .sb-form .sb-section td {
	background: #ececec;
	border-bottom: 0.3mm solid #888;
	font-weight: 600;
	padding-top: 1.8mm;
}

.sb-ustva .sb-form .sb-sum td {
	border-top: 0.3mm solid #000;
	font-weight: 600;
}

.sb-ustva .sb-form .sb-empty td {
	color: #666;
}

.sb-ustva col.sb-line,
.sb-ustva col.sb-kz {
	width: 10mm;
}

.sb-ustva col.sb-num {
	width: 31mm;
}

.sb-ustva .sb-line {
	color: #555;
}

.sb-ustva .sb-kz {
	text-align: center;
}

.sb-ustva .sb-num,
.sb-ustva .sb-form th.sb-num {
	text-align: right;
}

.sb-ustva td.sb-num {
	white-space: nowrap;
}

.sb-ustva .sb-flag {
	white-space: nowrap;
}

.sb-ustva .sb-note {
	color: #444;
}

.sb-ustva .sb-footer {
	border-top: 0.3mm solid #888;
	color: #444;
	font-size: 8pt;
	margin-top: 6mm;
	padding-top: 2mm;
}

.sb-ustva .sb-footer p {
	margin: 0 0 1mm;
}
